import java.io.*;
import java.util.*;

public class B {
    static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        FS in = new FS();
        long R = in.nextLong();
        long C = in.nextLong();
        long result = computeAnswer(Math.min(R, C), Math.max(R, C));
        out.println(result);
        out.close();
    }

    static long computeAnswer(long minDim, long maxDim) {
        if (minDim < 3 && maxDim < 3) return 0;
        if (minDim == 1) {
            long count = maxDim;
            long mod = maxDim % 6;
            if (mod != 0) {
                if (mod <= 3) count -= mod;
                else if (mod == 4) count -= 2;
                else if (mod == 5) count -= 1;
            }
            return count;
        }
        if (minDim == 2) {
            if (maxDim == 3 || maxDim == 7) return 2 * (maxDim - 1);
            return 2 * maxDim;
        }
        long total = minDim * maxDim;
        return (total % 2 == 0) ? total : total - 1;
    }

    static class FS {
        BufferedReader bufferedReader;
        StringTokenizer tokenizer;

        FS() {
            bufferedReader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            for (;;) {
                if (tokenizer != null && tokenizer.hasMoreTokens()) break;
                try {
                    tokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int[] NIA(int n) {
            int[] result = new int[n];
            for (int i = 0; i < n; i++) result[i] = nextInt();
            return result;
        }

        long[] NLA(int n) {
            long[] result = new long[n];
            for (int i = 0; i < n; i++) result[i] = nextLong();
            return result;
        }

        char[][] grid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }
}
